apiVersion: v1
kind: ConfigMap  # 定义logstash入数据和出数据的规则
metadata:
  name: logstash-config
  namespace: elastic

data:
  logstash.conf: |-
    input {
      kafka {
        bootstrap_servers => ["ip:9092"]
        group_id => "logstash-kafka"
        auto_offset_reset => "latest"
        consumer_threads => "12"
        decorate_events => "false"
        topics => ["test"]
        codec => json
      }
    }

    filter {
      date {
        match => [ "startDate", "UNIX_MS" ]
      }
      ruby { 
        code => "event.set('timestamp', event.get('@timestamp').time.localtime + 8*60*60)"
      }
      ruby {
        code => "event.set('index_date', event.get('timestamp').time.localtime.strftime('%Y.%m.%d.%H'))"
      }
      mutate {
        remove_field => ["timestamp"]
      }
    }

    output {
      elasticsearch {
        hosts => ["es 地址"]
        user => "username"
        password => "password"
        index => "test-%{index_date}"
      }
    }

apiVersion: v1
kind: ConfigMap
metadata:
  name: logstash-configmap
  namespace: kube-system
data:
  logstash.yml: |
    http.host: "0.0.0.0"
    path.config: /usr/share/logstash/pipeline
  logstash.conf: |
    # all input will come from filebeat, no local logs
    input {
      kafka {
              enable_auto_commit => true
              auto_commit_interval_ms => "1000"
              bootstrap_servers => "kafka.middleware:9092"
              topics => ["app-filebeat"]
              codec => json
          }
    }

    output {
       stdout{ codec=>rubydebug}
       if [fields][pod_namespace] =~ "default" {
           elasticsearch {
             hosts => ["elasticsearch-logging:9200"]
             index => "%{[fields][pod_namespace]}-s-%{+YYYY.MM.dd}"
          }
       } else {
          elasticsearch {
             hosts => ["elasticsearch-logging:9200"]
             index => "no-index-%{+YYYY.MM.dd}"
          }
       }
    }

