apiVersion: batch/v1
kind: Job
metadata:
  name: kafka-topic-creator
spec:
  template:
    spec:
      containers:
        - name: kafka-client
          image: confluentinc/cp-enterprise-kafka:5.5.0
          command:
            - sh
            - -c
            - >
              kafka-topics --bootstrap-server kafka-cp-kafka:9092 --create --topic hourofweek --partitions 3 --replication-factor 1;
              kafka-topics --bootstrap-server kafka-cp-kafka:9092 --create --topic hourofday --partitions 3 --replication-factor 1;
              kafka-topics --bootstrap-server kafka-cp-kafka:9092 --create --topic dayofweek --partitions 3 --replication-factor 1;
              kafka-topics --bootstrap-server kafka-cp-kafka:9092 --create --topic aggregation-feedback --partitions 3 --replication-factor 1;
              kafka-topics --bootstrap-server kafka-cp-kafka:9092 --create --topic input --partitions 3 --replication-factor 1;
              kafka-topics --bootstrap-server kafka-cp-kafka:9092 --create --topic configuration --partitions 3 --replication-factor 1;
              kafka-topics --bootstrap-server kafka-cp-kafka:9092 --create --topic output --partitions 3 --replication-factor 1;
      restartPolicy: OnFailure

apiVersion: v1
kind: ReplicationController
metadata:
  name: logstash-kafka-es-rc
spec:
  replicas: 1
  template:
    metadata:
      labels:
        app: logstash
    spec:
      containers:
      - name: logstash
        image: vungle/logstash-kafka-es:2.2.0
        imagePullPolicy: Always
        env:
        - name: ZK_CONNECT_LIST
          value: 172.16.33.211,172.16.31.246,172.16.32.92,172.16.31.247,172.16.32.186
        - name: KAFKA_TOPIC
          value: as-exchange
        - name: ES_URL
          value: 10.100.59.80:80
        - name: ES_INDEX
          value: as-exchange
        - name: BATCH_SIZE
          value: "10000"
#        - name: JAVA_OPTS
#          value: "-XX:+UseG1GC -Djava.awt.headless=true -XX:+HeapDumpOnOutOfMemoryError"
        - name: EXTRA_FILTERS
          value: |
            filter {
              grok {
                # break_on_match => true
                match => { "formatted_url" => ".*=%{IPV4:ex_device_ip}.*"}
                tag_on_failure => []
              }
              if [app_name] =~ /(?i)android/ {
                mutate {
                  add_field => { "ex_platform" => "android" }
                }
              }
              if [app_name] =~ /(?i)ios/ {
                mutate {
                  add_field => { "ex_platform" => "ios" }
                }
              }
              if [app_name] =~ /(?i)windows/ {
                mutate {
                  add_field => { "ex_platform" => "windows" }
                }
              }
              if [error] {
                grok {
                  break_on_match => true
                  match => { "error" => "Video bitrate must be above %{NUMBER:ex_min_bitrate}: bitrate was %{NUMBER:video_bitrate}"}
                  tag_on_failure => []
                }
              }
            }

